// FILE: js/systems/SaveSystem.js
const KEY='patent-examiner-rejection-legion-save-v1';
const DEF=()=>({version:1,coins:0,runs:0,highScore:0,bestTime:0,wins:0,unlocked:['marie','searcher','alchemist'],discoveries:[],kills:{},achievements:[],settings:{music:.33,sfx:.65,shake:true,flash:true,particles:'auto',education:true}});
function loadSave(){let d=DEF();try{const r=JSON.parse(localStorage.getItem(KEY)||'null');if(r&&typeof r==='object'){d={...d,...r,settings:{...d.settings,...r.settings},kills:typeof r.kills==='object'&&r.kills||{}};d.version=1}}catch(_e){}return d}
function persist(d){try{localStorage.setItem(KEY,JSON.stringify(d));return true}catch(e){console.warn('저장 실패',e);return false}}
function recordRun(save,game,won){save.runs++;save.coins+=Math.floor(game.kills/8)+game.bossesDefeated*55+(won?150:0);save.highScore=Math.max(save.highScore,game.score);save.bestTime=Math.max(save.bestTime,Math.floor(game.elapsed));if(won)save.wins++;for(let en of game.encountered)if(!save.discoveries.includes(en))save.discoveries.push(en);for(let k of Object.keys(game.killLog))save.kills[k]=(save.kills[k]||0)+game.killLog[k];const badge=(id,c)=>{if(c&&!save.achievements.includes(id))save.achievements.push(id)};badge('first',save.runs>=1);badge('hunter',save.highScore>=2000);badge('survivor',save.bestTime>=300);badge('champion',save.wins>=1);badge('collector',save.discoveries.length>=12);persist(save)}

// FILE: js/engine/Audio.js
/** Fully original realtime synthesized audio; no third-party music, no network. */
class GameAudio {
 constructor(){this.ctx=null;this.music=.33;this.sfx=.65;this.step=0;this.next=0;this.muted=false;this.buffers={};this.loading=false}
 unlock(){try{this.ctx??=new (window.AudioContext||window.webkitAudioContext)();if(this.ctx.state==='suspended')this.ctx.resume();if(!this.loading)this.loadSamples()}catch(e){console.warn('Web Audio 불가',e)}}
 async loadSamples(){this.loading=true;const names=['blade','laser','chain','shield','drone','markush','hit','critical','xp','level','upgrade','boss','danger','dash','ultimate','death','win','click'];await Promise.all(names.map(async name=>{try{const r=await fetch(`./assets/audio/${name}.wav`);if(!r.ok)return;this.buffers[name]=await this.ctx.decodeAudioData(await r.arrayBuffer())}catch(_e){}}))}
 tone(freq=440,dur=.12,typ='sine',vol=.12,slide=1,when=0){if(!this.ctx||!this.sfx)return;const t=Math.max(this.ctx.currentTime,this.ctx.currentTime+when),o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=typ;o.frequency.setValueAtTime(Math.max(20,freq),t);o.frequency.exponentialRampToValueAtTime(Math.max(20,freq*slide),t+dur);g.gain.setValueAtTime(Math.max(.0001,vol*this.sfx),t);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g);g.connect(this.ctx.destination);o.start(t);o.stop(t+dur+.01)}
 sound(type){if(!this.ctx)return;if(this.buffers[type]){try{const src=this.ctx.createBufferSource(),gain=this.ctx.createGain();src.buffer=this.buffers[type];gain.gain.value=Math.min(1,this.sfx)*.55;src.connect(gain).connect(this.ctx.destination);src.start();return}catch(_e){}}switch(type){case'blade':this.tone(690,.085,'sawtooth',.1,.34);break;case'laser':this.tone(1100,.18,'sine',.12,.46);break;case'chain':this.tone(270,.15,'square',.065,2.5);break;case'shield':this.tone(155,.3,'triangle',.17,2);break;case'drone':this.tone(540,.1,'triangle',.09,.6);break;case'markush':this.tone(360,.38,'sine',.12,1.6);break;case'hit':this.tone(140,.07,'sawtooth',.035,.4);break;case'critical':this.tone(680,.23,'triangle',.17,2);break;case'xp':this.tone(820,.065,'sine',.05,1.3);break;case'level':for(let i=0;i<5;i++)this.tone([440,554,659,880,1108][i],.23,'sine',.2,1,i*.075);break;case'upgrade':this.tone(660,.24,'triangle',.17,1.45);break;case'boss':for(let i=0;i<3;i++)this.tone([130,110,90][i],.54,'sawtooth',.2,.85,i*.17);break;case'danger':this.tone(210,.22,'square',.08,.85);break;case'dash':this.tone(340,.2,'triangle',.18,2);break;case'ultimate':for(let i=0;i<6;i++)this.tone(150+i*125,.52,'sawtooth',.11,1.5,i*.06);break;case'death':this.tone(240,.68,'triangle',.22,.25);break;case'win':for(let i=0;i<6;i++)this.tone([392,523,659,784,1047,1318][i],.42,'sine',.23,1,i*.12);break;case'click':this.tone(560,.075,'sine',.06,1.25);break}}
 tick(dt,running){if(!this.ctx||!running||this.music<=0)return;this.next-=dt;if(this.next>0)return;this.next+=.26;const notes=[196,247,294,392,330,294,247,392,220,262,330,440,392,330,294,247];const t=notes[this.step%notes.length];const before=this.sfx;this.sfx=this.music*.55;this.tone(t,.20,'triangle',.08,1);if(this.step%4===0)this.tone(t/2,.40,'sine',.06,1);this.sfx=before;this.step++}
}

// FILE: js/engine/Input.js
class Input {
 constructor(canvas, dash, pause){this.canvas=canvas;this.keys=new Set();this.touch=null;this.dashRequested=false;this.dash=dash;this.pause=pause;this.setListeners()}
 setListeners(){window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.repeat&&['Space','Escape'].includes(e.code))return;this.keys.add(e.code);if(e.code==='Space')this.dashRequested=true;if(e.code==='Escape')this.pause()},{passive:false});window.addEventListener('keyup',e=>this.keys.delete(e.code));window.addEventListener('blur',()=>this.clear());document.addEventListener('visibilitychange',()=>{if(document.hidden)this.clear()});
 this.canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse')return;if(e.clientX>innerWidth*.7)return;this.touch={id:e.pointerId,x:e.clientX,y:e.clientY,dx:0,dy:0};this.canvas.setPointerCapture(e.pointerId);e.preventDefault()},{passive:false});this.canvas.addEventListener('pointermove',e=>{if(!this.touch||e.pointerId!==this.touch.id)return;const dx=e.clientX-this.touch.x,dy=e.clientY-this.touch.y,mag=Math.hypot(dx,dy),max=62;this.touch.dx=mag>max?dx/mag:dx/max;this.touch.dy=mag>max?dy/mag:dy/max;e.preventDefault()},{passive:false});for(const ev of ['pointerup','pointercancel','lostpointercapture'])this.canvas.addEventListener(ev,e=>{if(this.touch?.id===e.pointerId)this.touch=null});dash.addEventListener('pointerdown',e=>{e.preventDefault();this.dashRequested=true},{passive:false})}
 getVector(){let x=Number(this.keys.has('KeyD')||this.keys.has('ArrowRight'))-Number(this.keys.has('KeyA')||this.keys.has('ArrowLeft'));let y=Number(this.keys.has('KeyS')||this.keys.has('ArrowDown'))-Number(this.keys.has('KeyW')||this.keys.has('ArrowUp'));if(this.touch){x+=this.touch.dx;y+=this.touch.dy}const l=Math.hypot(x,y);return l>1?{x:x/l,y:y/l}:{x,y}}
 consumeDash(){const yes=this.dashRequested;this.dashRequested=false;return yes}
 clear(){this.keys.clear();this.touch=null;this.dashRequested=false}
}

