 for(const area of g.areas){if(!visible(area,area.r+50))continue;c.save();c.translate(sx(area.x),sy(area.y));c.globalAlpha=Math.min(.6,area.ttl*2)*(.65+.1*Math.sin(g.elapsed*12));c.strokeStyle=area.color;c.fillStyle=area.color+'22';c.lineWidth=4;c.beginPath();c.arc(0,0,area.r,0,Math.PI*2);c.fill();c.stroke();for(let n=0;n<6;n++){const a=n*Math.PI/3+g.elapsed*.7;c.beginPath();c.arc(0,0,area.r*.8,a,a+.38);c.stroke()}c.restore()}
 // enemies and players are sprites with frame metadata and alpha; position sorted for depth
