 for(const item of items){if(item.player){const p=g.player,x=sx(p.x),y=sy(p.y);const blink=p.invuln>0&&Math.floor(g.elapsed*22)%2?.57:1;c.save();c.shadowColor=p.character.color;c.shadowBlur=16;c.fillStyle='#0b1330bb';c.beginPath();c.ellipse(x,y+5,25,9,0,0,Math.PI*2);c.fill();c.restore();this.drawSprite('characters',p.character.id,p.anim,x,y,148,p.animT,p.facing<0,blink);continue}
 const e=item.entity,x=sx(e.x),y=sy(e.y);c.fillStyle='#0207176a';c.beginPath();c.ellipse(x,y+e.radius*.5,e.radius*.85,e.radius*.32,0,0,6.283);c.fill();if(e.hitFlash>0&&g.save.settings.flash)c.filter='brightness(2.4) saturate(.35)';this.drawSprite(e.boss?'bosses':'enemies',e.id,e.dead?'death':e.hitFlash>.12?'hit':e.attackAnim>0?'attack':'move',x,y,e.boss?e.radius*3.7:e.radius*3.65,e.animT,e.facing<0,e.dead?Math.max(0,e.fade):1);c.filter='none';if(e.boss||e.elite){const bw=e.radius*1.75,per=Math.max(0,e.hp/e.maxHp);c.fillStyle='#101023';c.fillRect(x-bw/2,y-e.radius*1.32,bw,6);c.fillStyle=e.boss?'#f58ddf':'#ffc16e';c.fillRect(x-bw/2,y-e.radius*1.32,bw*per,6)}}
 // weapons / projectiles all rendered on top of sprites
