 updatePickups(dt){const p=this.player;for(let i=this.pickups.length-1;i>=0;i--){const o=this.pickups[i],dist=len(o,p),mag=120*Math.pow(1.45,this.stats.magnet);if(dist<mag){const n=norm(p.x-o.x,p.y-o.y),spd=clamp(160+(mag-dist)*5,160,900);o.x+=n.x*spd*dt;o.y+=n.y*spd*dt}if(dist<30){this.pickups.splice(i,1);if(o.type==='heal')p.hp=Math.min(p.maxHp,p.hp+o.value);else{p.xp+=o.value;if(this.kills%4===0)this.audio.sound('xp');if(p.xp>=p.need){p.xp-=p.need;p.level++;p.need=Math.round(12+p.level*6.5);this.openLevelUp();break}}}}}
 spawnProp(){if(this.props.length>24)return;const types=['crystal','crystal','archive','archive','healing','portal','burst'];const kind=types[Math.floor(Math.random()*types.length)],a=rand(0,Math.PI*2),r=rand(240,850);const p=this.player;this.props.push({type:kind,x:clamp(p.x+Math.cos(a)*r,100,3900),y:clamp(p.y+Math.sin(a)*r,100,3900),r:26,ttl:200,seed:rand(0,30)})}
 updateProps(dt){for(let i=this.props.length-1;i>=0;i--){const o=this.props[i];o.ttl-=dt;if(o.ttl<=0){this.props.splice(i,1);this.spawnProp();continue}if(len(o,this.player)>65)continue;this.props.splice(i,1);this.spark(o.x,o.y,o.type==='healing'?'#a5ffc7':'#f9d796',15);this.ring(o.x,o.y,75,'#b5faff',.5);switch(o.type){case'crystal':this.player.xp+=9+this.player.level*2;this.score+=120;this.ui.toast('판단력 결정 획득 · EXP 보너스!');break;case'archive':this.score+=380;this.player.xp+=7;this.ui.toast('선행기술 아카이브 수집 · +380점');break;case'healing':this.player.hp=Math.min(this.player.maxHp,this.player.hp+42);this.ui.toast('회복 데이터 +42 HP');break;case'portal':this.player.x=clamp(this.player.x+rand(-250,250),120,3880);this.player.y=clamp(this.player.y+rand(-250,250),120,3880);this.player.invuln=1;this.ui.toast('데이터 포털 · 순간 이동!');break;case'burst':for(const e of this.enemies){if(!e.dead&&len(e,o)<240)this.damage(e,140,{x:o.x,y:o.y},false,1.7)}this.score+=200;this.ui.toast('심사 판단 폭풍 · 광역 타격!');break}this.audio.sound('upgrade');this.spawnProp();if(this.player.xp>=this.player.need&&this.state==='playing'){this.player.xp-=this.player.need;this.player.level++;this.player.need=Math.round(12+this.player.level*6.5);this.openLevelUp()}}
 }
 scan(){if(this.state!=='playing'||this.scanCD>0)return;this.scanCD=17;this.scanTimer=4.5;this.scanPulse=.58;this.ring(this.player.x,this.player.y,340,'#80fef0',.75);this.audio.sound('laser');this.ui.toast('문헌 스캔! 4.5초간 적이 받는 피해 +28%')}
 updateEffects(dt){for(let i=this.effects.length-1;i>=0;i--)if((this.effects[i].life-=dt)<=0)this.effects.splice(i,1)}
 openLevelUp(){if(this.state!=='playing')return;this.state='levelup';this.audio.sound('level');const choices=this.getChoices();this.ui.showLevelUp(choices,this)}
 getChoices(){const opts=[];for(const id of Object.keys(WEAPONS)){const lv=this.weapons[id]||0;if(lv<5)opts.push({kind:'weapon',id,name:lv?`${WEAPONS[id].name} Lv.${lv+1}`:`신규 무기 · ${WEAPONS[id].name}`,desc:lv?`피해 +30%, 공격 효과 강화`:`${WEAPONS[id].desc}`,icon:id,rare:lv===4})}
 for(const id of Object.keys(STATS))if(this.stats[id]<(id==='projectile'?2:5))opts.push({kind:'stat',id,...STATS[id],icon:STATS[id].icon,rare:false});for(const ev of EVOLUTIONS)if(!this.evolutions.has(ev.id)&&ev.requires.every(w=>this.weapons[w]>=5))opts.push({kind:'evolution',id:ev.id,name:'진화 · '+ev.name,desc:ev.desc,icon:ev.requires[0],rare:true});let chosen=[],rare=opts.filter(x=>x.rare);if(rare.length)chosen.push(rare[Math.floor(Math.random()*rare.length)]);while(chosen.length<3&&opts.length){const candidates=opts.filter(x=>!chosen.includes(x));if(!candidates.length)break;chosen.push(candidates[Math.floor(Math.random()*candidates.length)])}return chosen.sort(()=>Math.random()-.5)}
 applyChoice(o){if(this.state!=='levelup')return;if(o.kind==='weapon')this.weapons[o.id]=(this.weapons[o.id]||0)+1;else if(o.kind==='stat'){this.stats[o.id]++;if(o.id==='health'){this.player.maxHp+=25;this.player.hp=Math.min(this.player.maxHp,this.player.hp+35)}}else if(o.kind==='evolution'){this.evolutions.add(o.id);this.ui.toast(`${o.name} 활성화!`)}this.state='playing';this.audio.sound('upgrade');this.ui.hideLevelUp();this.ui.refreshHUD(this)}
 showPatentEvent(){if(this.state!=='playing')return;const q=PATENT_CASES[(this.bossesDefeated-1)%PATENT_CASES.length];this.state='event';this.ui.showCase(q,(correct)=>{if(correct){this.score+=800;this.player.hp=Math.min(this.player.maxHp,this.player.hp+25)}this.state='playing'})}
