 document.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>{if(this.backTo==='pause'){this.show('title');this.screens().forEach(el=>el.classList.add('hidden'));$('#modal-pause').classList.remove('hidden');this.backTo='title'}else this.title()});
 document.querySelectorAll('[data-mode]').forEach(btn=>btn.addEventListener('click',()=>{this.mode=btn.dataset.mode;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b===btn))}));
 $('#start-game').onclick=()=>this.game.start(this.char,this.stage,this.mode);
 $('#pause-btn').onclick=()=>this.game.pause();$('#resume').onclick=()=>this.game.pause();$('#quit').onclick=()=>this.title();$('#pause-settings').onclick=()=>this.openSettings(true);$('#retry').onclick=()=>this.game.start(this.char,this.stage,this.mode);$('#home').onclick=()=>this.title();
 $('#ult-btn').onclick=()=>this.game.ultimate();$('#scan-btn').onclick=()=>this.game.scan();window.addEventListener('keydown',e=>{if(e.code==='KeyQ'&&!e.repeat&&this.game)this.game.ultimate();if(e.code==='KeyE'&&!e.repeat&&this.game)this.game.scan()});
 $('#rotate-close').onclick=()=>{this.rotateDismiss=true;this.maybeRotate()};window.addEventListener('resize',()=>this.maybeRotate());
