 initCards(){const box=$('#character-list');box.innerHTML='';for(const char of CHARACTERS){let b=document.createElement('button');b.type='button';b.className='char-card'+(char.id===this.char?' selected':'');b.innerHTML=`<img src="./assets/portraits/${char.id}.webp" alt="${char.name}"><strong>${char.name}</strong><small>${char.role}</small>`;b.title=char.desc;b.onclick=()=>{this.char=char.id;box.querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b));this.audio.sound('click')};box.appendChild(b)}const stages=$('#stage-list');stages.innerHTML='';for(const s of STAGES){let b=document.createElement('button');b.className='stage-card'+(this.stage===s.id?' selected':'');b.style.backgroundImage=`url('./${s.background}')`;b.innerHTML=`<strong>${s.name}</strong><small>${s.desc}</small>`;b.onclick=()=>{this.stage=s.id;stages.querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b));this.audio.sound('click')};stages.appendChild(b)}}
