 openAchievements(){this.show('achievements');$('#record-stats').innerHTML=`<div class="record"><strong>${this.save.runs}</strong><small>도전 횟수</small></div><div class="record"><strong>${this.save.highScore.toLocaleString()}</strong><small>최고 점수</small></div><div class="record"><strong>${fmt(this.save.bestTime)}</strong><small>최장 생존</small></div><div class="record"><strong>${this.save.wins}</strong><small>클리어</small></div>`;let defs=[['first','첫 번째 출격','게임에 처음 출격했습니다.'],['hunter','오류 포획자','점수 2,000점 달성'],['survivor','생존 전문가','5분 생존'],['champion','심사 수호자','보스 3종 격파'],['collector','군단 관찰자','몬스터 12종 조우']];$('#achievement-list').innerHTML=defs.map(([id,t,d])=>`<div class="codex-card ${this.save.achievements.includes(id)?'':'locked'}"><img src="${icon(this.save.achievements.includes(id)?'coins':'shield')}" alt=""><strong>${t} ${this.save.achievements.includes(id)?'✓':'· 미완료'}</strong><p>${d}</p></div>`).join('')}
