 syncSettings(){for(const id of ['music','sfx','particles','shake','flash','education']){const el=$('#'+id);if(el.type==='checkbox')el.checked=!!this.save.settings[id];else el.value=this.save.settings[id]}} 
 updateSettings(){const d=this.save.settings;for(const id of ['music','sfx','particles','shake','flash','education']){const el=$('#'+id);d[id]=el.type==='checkbox'?el.checked:el.type==='range'?Number(el.value):el.value}persist(this.save);this.audio.music=d.music;this.audio.sfx=d.sfx}
 refreshHUD(g){const p=g.player;$('#hud-name').textContent=p.character.name;$('#hud-level').textContent='Lv.'+p.level;$('#avatar').textContent=p.character.id==='marie'?'M':p.character.id==='searcher'?'S':'A';$('#hp-fill').style.width=`${clampPct(p.hp/p.maxHp)}%`;$('#hp-text').textContent=`${Math.ceil(p.hp)} / ${p.maxHp}`;$('#xp-fill').style.width=`${clampPct(p.xp/p.need)}%`;$('#xp-label').textContent=`${Math.floor(p.xp)} / ${p.need}`;$('#time-text').textContent=fmt(g.elapsed);$('#kill-text').textContent=g.kills.toLocaleString();$('#combo').textContent=`${g.combo} COMBO`;$('#combo').classList.toggle('hidden',g.combo<5);$('#boss-meter').classList.toggle('hidden',!g.boss||g.boss.dead);if(g.boss){$('#boss-name').textContent=g.boss.name+(g.boss.phase===2?' · 2페이즈':'');$('#boss-fill').style.width=`${clampPct(g.boss.hp/g.boss.maxHp)}%`;$('#boss-percent').textContent=Math.max(0,Math.round(g.boss.hp/g.boss.maxHp*100))+'%'}
 $('#scan-cooldown').textContent=g.scanCD>0?Math.ceil(g.scanCD)+'s':'READY';$('#scan-btn').classList.toggle('unavailable',g.scanCD>0);$('#dash-cooldown').textContent=p.dashCD>0?p.dashCD.toFixed(1)+'s':'READY';$('#ult-cooldown').textContent=p.ultCD>0?Math.ceil(p.ultCD)+'s':'READY';$('#dash-btn').classList.toggle('unavailable',p.dashCD>0);$('#ult-btn').classList.toggle('unavailable',p.ultCD>0);const weaponString=JSON.stringify(g.weapons);if(this.lastWeapons!==weaponString){this.lastWeapons=weaponString;$('#weapon-strip').innerHTML=Object.entries(g.weapons).map(([id,l])=>`<div class="weapon-chip" title="${WEAPONS[id].name} Lv.${l}"><img src="${icon(id)}" alt="${WEAPONS[id].name}"><small>${l}</small></div>`).join('')}}
 showLevelUp(cards,g){const el=$('#level-cards');el.innerHTML='';for(const c of cards){const b=document.createElement('button');b.className=c.rare?'rare':'';b.innerHTML=`<img src="${icon(c.icon)}" alt=""><strong>${c.name}</strong><span>${c.desc}</span>${c.rare?'<em>RARE · 고급 강화</em>':''}`;b.onclick=()=>g.applyChoice(c);el.appendChild(b)}$('#modal-level').classList.remove('hidden')}
 hideLevelUp(){$('#modal-level').classList.add('hidden')}
