 finish(g,won){$('#hud').classList.add('hidden');$('#modal-result').classList.remove('hidden');$('#result-art').style.backgroundImage=`url('./assets/backgrounds/${won?'ending':'boss_shadow'}.webp')`;$('#result-label').textContent=won?'MISSION COMPLETE':'MISSION FAILED';$('#result-title').textContent=won?'심사 시스템을 지켜냈습니다!':'다음 심사에서는 더 정확하게!';$('#result-stats').innerHTML=`<div><b>${fmt(g.elapsed)}</b><span>생존 시간</span></div><div><b>${g.kills}</b><span>처치 수</span></div><div><b>${g.score.toLocaleString()}</b><span>획득 점수</span></div><div><b>${g.player.level}</b><span>최종 레벨</span></div><div><b>${g.bossesDefeated} / 3</b><span>보스 격파</span></div><div><b>${Object.keys(g.weapons).length}</b><span>보유 무기</span></div>`}
